CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,name_en TEXT,description TEXT,description_en TEXT,published INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,name_en TEXT,category TEXT,brand TEXT,sku TEXT,description TEXT,description_en TEXT,price_cents INTEGER NOT NULL CHECK(price_cents>=0),price_verified INTEGER DEFAULT 0,variant_label TEXT,variant_label_en TEXT,variants TEXT,in_stock INTEGER DEFAULT 1,taxable INTEGER DEFAULT 1,published INTEGER DEFAULT 1,featured INTEGER DEFAULT 0,sort_order INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category);
CREATE TABLE IF NOT EXISTS bundles (id SERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,name_en TEXT,grade TEXT,grade_en TEXT,description TEXT,description_en TEXT,items TEXT,published INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY,user_id TEXT,request_key TEXT,reference TEXT UNIQUE,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,fulfilment TEXT NOT NULL DEFAULT 'pickup' CHECK(fulfilment IN ('pickup','shipping')),address_line TEXT,address_city TEXT,address_province TEXT,address_postal TEXT,note TEXT,tracking TEXT,status TEXT DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','paid','preparing','ready','shipped','fulfilled','cancelled')),subtotal_cents INTEGER NOT NULL DEFAULT 0,shipping_cents INTEGER NOT NULL DEFAULT 0,gst_cents INTEGER NOT NULL DEFAULT 0,qst_cents INTEGER NOT NULL DEFAULT 0,total_cents INTEGER NOT NULL DEFAULT 0,consent INTEGER DEFAULT 0,terms_snapshot TEXT,privacy_snapshot TEXT,payment_status TEXT DEFAULT 'unpaid',order_key TEXT UNIQUE,capture_key TEXT,paypal_order_id TEXT UNIQUE,paypal_capture_id TEXT UNIQUE,paypal_mode TEXT,paypal_client_hash TEXT,order_started_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,checked_at TIMESTAMPTZ,email_state TEXT DEFAULT 'not_sent',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS order_items (id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,name_snapshot TEXT NOT NULL,variant TEXT,unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),quantity INTEGER NOT NULL CHECK(quantity>0 AND quantity<=20),line_cents INTEGER NOT NULL CHECK(line_cents>=0),taxable INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id);
CREATE TABLE IF NOT EXISTS hours (id SERIAL PRIMARY KEY,weekday INTEGER NOT NULL UNIQUE CHECK(weekday BETWEEN 1 AND 7),opens TEXT,closes TEXT,closed INTEGER DEFAULT 0,note TEXT,note_en TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT,email TEXT NOT NULL,phone TEXT,subject TEXT,body TEXT NOT NULL,consent INTEGER DEFAULT 0,privacy_snapshot TEXT,status TEXT DEFAULT 'new' CHECK(status IN ('new','read','answered','archived')),email_state TEXT DEFAULT 'not_sent',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
